-- chair-step: inverse of read_lane_v2_b3_19_workbench_working_documents — un-enrolls workbench.working_documents from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'working_documents' and is_active);
select iam.apply_rls('workbench', 'working_documents', (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'working_documents' and is_active), (select rls_variant from platform.entity_types where schema_name = 'workbench' and table_name = 'working_documents' and is_active));
